import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import axios from 'axios';
import { useLanguage } from '../context/LanguageContext';

const AdminSettings = () => {
    const navigate = useNavigate();
    const location = useLocation();
    const { t, changeLanguage } = useLanguage();
    const [user, setUser] = useState(null);
    const [showModal, setShowModal] = useState(false);
    const [modalType, setModalType] = useState('');
    const [formData, setFormData] = useState({});
    const [selectedFile, setSelectedFile] = useState(null);

    // Load user from localStorage FIRST, then refresh from API
    useEffect(() => {
        const storedUser = localStorage.getItem('user');
        if (storedUser) {
            const userData = JSON.parse(storedUser);
            // Check if user is admin
            if (userData.role !== 'admin') {
                navigate('/services');
                return;
            }
            setUser(userData);
        }

        const fetchUser = async () => {
            try {
                const token = localStorage.getItem('token');
                const res = await axios.get('http://localhost:5000/api/auth/me', {
                    headers: { Authorization: `Bearer ${token}` }
                });
                setUser(res.data.user);
                localStorage.setItem('user', JSON.stringify(res.data.user));
            } catch (err) {
                console.error("Error fetching user", err);
            }
        };
        fetchUser();
    }, [navigate]);

    const handleLogout = () => {
        localStorage.removeItem('token');
        localStorage.removeItem('user');
        navigate('/admin-login');
    };

    const isActive = (path) => location.pathname === path;

    const openModal = (type) => {
        setModalType(type);
        setFormData({});
        setSelectedFile(null);
        setShowModal(true);
    };

    const closeModal = () => {
        setShowModal(false);
        setModalType('');
        setFormData({});
        setSelectedFile(null);
    };

    const handleFileChange = (e) => setSelectedFile(e.target.files[0]);
    const handleChange = (e) => setFormData({ ...formData, [e.target.name]: e.target.value });

    const handleSubmit = async (e) => {
        e.preventDefault();
        try {
            const token = localStorage.getItem('token');

            // 1. PICTURE
            if (modalType === 'picture' && selectedFile) {
                const reader = new FileReader();
                reader.readAsDataURL(selectedFile);
                reader.onload = async () => {
                    try {
                        const res = await axios.put('http://localhost:5000/api/auth/update-profile-image', 
                            { profileImage: reader.result },
                            { headers: { Authorization: `Bearer ${token}` } }
                        );
                        setUser(res.data.user);
                        localStorage.setItem('user', JSON.stringify(res.data.user));
                        alert("✅ Picture updated!");
                        closeModal();
                    } catch (err) { alert("❌ Failed to upload picture."); }
                };
            } 
            // 2. DELETE PICTURE
            else if (modalType === 'deletePicture') {
                try {
                    const res = await axios.put('http://localhost:5000/api/auth/update-profile-image', 
                        { profileImage: null },
                        { headers: { Authorization: `Bearer ${token}` } }
                    );
                    setUser(res.data.user);
                    localStorage.setItem('user', JSON.stringify(res.data.user));
                    alert("✅ Picture deleted!");
                    closeModal();
                } catch (err) { alert("❌ Failed to delete picture."); }
            }
            // 3. PASSWORD
            else if (modalType === 'password') {
                if (formData.newPassword !== formData.confirmPassword) { alert("❌ Passwords do not match!"); return; }
                if (formData.newPassword.length < 8) { alert("❌ Password must be at least 8 characters!"); return; }

                try {
                    await axios.put('http://localhost:5000/api/auth/update', 
                        { password: formData.newPassword },
                        { headers: { Authorization: `Bearer ${token}` } }
                    );
                    alert("✅ Password changed! Please login again.");
                    localStorage.removeItem('token'); localStorage.removeItem('user');
                    navigate('/admin-login');
                } catch (err) { alert("❌ Failed to change password."); }
            }
            // 4. LANGUAGE
            else if (modalType === 'language') {
                await changeLanguage(formData.language);
                alert("✅ Language changed!");
                closeModal();
            }
            // 5. NAME, EMAIL/PHONE
            else {
                let updateData = {};
                if (modalType === 'name') {
                    updateData = { firstName: formData.firstName, lastName: formData.lastName };
                } else if (modalType === 'emailPhone') {
                    if (formData.email) updateData.email = formData.email;
                    if (formData.phone) updateData.phone = formData.phone;
                }

                try {
                    const res = await axios.put('http://localhost:5000/api/auth/update', updateData, {
                        headers: { Authorization: `Bearer ${token}` }
                    });
                    setUser(res.data.user);
                    localStorage.setItem('user', JSON.stringify(res.data.user));
                    alert("✅ Changes saved!");
                    closeModal();
                } catch (err) { alert("❌ Failed to update."); }
            }
        } catch (err) { alert("❌ Failed to update."); }
    };

    return (
        <div className="settings-page">
            <nav className="settings-navbar">
                <div className="nav-logo">BeautyBook Admin</div>
                <div className="nav-links-desktop">
                    <span className={`nav-item ${isActive('/admin/dashboard') ? 'active' : ''}`} onClick={() => navigate('/admin/dashboard')}>
                        📊 Dashboard
                    </span>
                    <span className={`nav-item ${isActive('/admin/appointments') ? 'active' : ''}`} onClick={() => navigate('/admin/appointments')}>
                        📅 Appointments
                    </span>
                    <span className={`nav-item ${isActive('/admin/settings') ? 'active' : ''}`}>
                        ⚙️ Settings
                    </span>
                    <span className="nav-item" onClick={handleLogout} style={{cursor: 'pointer', color: '#d32f2f'}}>
                        🚪 Logout
                    </span>
                </div>
            </nav>

            <div className="settings-content">
                <div className="decorative-icons">
                    <span className="icon-1">💄</span>
                    <span className="icon-2">🌸</span>
                    <span className="icon-3">💅</span>
                    <span className="icon-4">🧴</span>
                    <span className="icon-5">💋</span>
                    <span className="icon-6">🪞</span>
                </div>

                <div className="settings-card">
                    <div className="profile-section">
                        <div className="profile-avatar">
                            {user && user.profileImage ? (
                                <img src={user.profileImage} alt="Profile" className="profile-image" />
                            ) : (
                                <svg width="80" height="80" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                                    <circle cx="12" cy="12" r="12" fill="#fce4b8" />
                                    <circle cx="12" cy="9.5" r="4" fill="#f8c3a1" />
                                    <path d="M4 20c0-3.87 3.58-7 8-7s8 3.13 8 7" fill="#c4a35a" />
                                </svg>
                            )}
                        </div>
                        <h2 className="profile-name">{user?.firstName || user?.lastName ? `${user.firstName || ''} ${user.lastName || ''}` : 'Admin'}</h2>
                        <p style={{ color: '#888', fontSize: '14px', fontFamily: 'Inter, sans-serif' }}>
                            {user?.role === 'admin' ? '👑 Administrator' : '👤 Client'}
                        </p>
                    </div>

                    <div className="settings-buttons">
                        <button className="setting-btn" onClick={() => openModal('picture')}>📸 Change Profile Picture</button>
                        <button className="setting-btn" onClick={() => openModal('deletePicture')}>🗑️ Delete Profile Picture</button>
                        <button className="setting-btn" onClick={() => openModal('name')}>✏️ Change Name</button>
                        <button className="setting-btn" onClick={() => openModal('password')}>🔑 Change Password</button>
                        <button className="setting-btn" onClick={() => openModal('language')}>🌍 Change Language</button>
                        <button className="setting-btn" onClick={() => openModal('emailPhone')}>📧 Change Email / Phone</button>
                    </div>
                </div>
            </div>

            {showModal && (
                <div className="settings-modal-overlay" onClick={closeModal}>
                    <div className="settings-modal" onClick={(e) => e.stopPropagation()}>
                        <h3>Update Settings</h3>
                        <form onSubmit={handleSubmit}>
                            {modalType === 'picture' && (
                                <>
                                    <label>Upload New Picture:</label>
                                    <input type="file" accept="image/*" onChange={handleFileChange} required />
                                </>
                            )}
                            {modalType === 'deletePicture' && <p style={{color: '#d32f2f'}}>Are you sure you want to delete your picture?</p>}
                            {modalType === 'name' && (
                                <>
                                    <input type="text" name="firstName" placeholder="First Name" onChange={handleChange} required />
                                    <input type="text" name="lastName" placeholder="Last Name" onChange={handleChange} required />
                                </>
                            )}
                            {modalType === 'password' && (
                                <>
                                    <input type="password" name="newPassword" placeholder="New Password" onChange={handleChange} required />
                                    <input type="password" name="confirmPassword" placeholder="Confirm Password" onChange={handleChange} required />
                                </>
                            )}
                            {modalType === 'emailPhone' && (
                                <>
                                    <input type="email" name="email" placeholder="Email (optional)" onChange={handleChange} />
                                    <input type="text" name="phone" placeholder="Phone (optional)" onChange={handleChange} />
                                </>
                            )}
                            {modalType === 'language' && (
                                <select name="language" onChange={handleChange} defaultValue={user?.language || 'fr'} required>
                                    <option value="fr">French</option>
                                    <option value="en">English</option>
                                    <option value="ar">Arabic</option>
                                </select>
                            )}
                            <div className="modal-actions">
                                <button type="button" className="cancel-modal-btn" onClick={closeModal}>Cancel</button>
                                <button type="submit" className="confirm-booking-btn">Save</button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
};

export default AdminSettings;
